-- ================= Lịch sử chuyển trạng thái đơn tiệc =================
SELECT id, 'PENDING', 'CONFIRMED', 'admin@vuonsen.vn', N'Đã liên hệ khách và nhận cọc', created_at
FROM bookings WHERE status IN ('CONFIRMED', 'COMPLETED') AND code LIKE 'VS-%-5%';
SELECT id, 'CONFIRMED', 'COMPLETED', 'admin@vuonsen.vn', N'Tiệc đã diễn ra xong', created_at
FROM bookings WHERE status = 'COMPLETED' AND code LIKE 'VS-%-5%';
SELECT id, 'PENDING', 'CANCELLED', 'admin@vuonsen.vn', N'Khách báo hoãn', created_at
FROM bookings WHERE status = 'CANCELLED' AND code LIKE 'VS-%-5%';

