-- ================= Phiếu thu tương ứng, dựng từ số tiền đã ghi trên đơn =================
                      reference, note, confirmed_by, confirmed_at, created_at)
SELECT CONCAT('TT-B-', SUBSTRING(b.code, 4)), 'BOOKING', b.id,
       CASE WHEN b.deposit_paid >= b.total_amount THEN 'FULL' ELSE 'DEPOSIT' END,
       b.deposit_paid, 'TRANSFER', 'CONFIRMED', b.code,
       N'Dựng từ dữ liệu quy mô lớn', 'admin@vuonsen.vn',
       COALESCE(b.deposit_paid_at, b.created_at), COALESCE(b.deposit_paid_at, b.created_at)
FROM bookings b WHERE b.deposit_paid > 0 AND b.code LIKE 'VS-%-5%';

                      reference, note, confirmed_by, confirmed_at, created_at)
SELECT CONCAT('TT-M-', SUBSTRING(o.code, 4)), 'DISH_ORDER', o.id, 'FULL', o.paid_amount,
       COALESCE(o.payment_method, 'CASH'), 'CONFIRMED', o.code,
       N'Dựng từ dữ liệu quy mô lớn', 'admin@vuonsen.vn', o.serve_at, o.serve_at
FROM dish_orders o WHERE o.paid_amount > 0 AND o.code LIKE 'DM-%-5%';

